const rows = $input.all().map(i => i.json);

const labels = {
  DFF: 'Lai suat Fed (Federal Funds Rate, %)',
  CPIAUCSL: 'Chi so gia tieu dung CPI (lam phat)',
  DTWEXBGS: 'Chi so do la My (DXY, cang cao thi crypto/tai san rui ro thuong cang yeu)',
  UNRATE: 'Ty le that nghiep My (%)'
};

const bySeries = {};
for (const r of rows) {
  if (!bySeries[r.series_id]) bySeries[r.series_id] = [];
  bySeries[r.series_id].push(r);
}

const lines = [];
for (const seriesId in bySeries) {
  const arr = bySeries[seriesId].sort((a, b) => new Date(a.observation_date) - new Date(b.observation_date));
  const first = arr[0].value;
  const last = arr[arr.length - 1].value;
  const change = (last - first).toFixed(2);
  lines.push(`- ${labels[seriesId] || seriesId}: gia tri gan nhat ${last} (thay doi ${change} so voi ${arr.length} ky truoc)`);
}

const prompt = `Ban la Macro Agent, chuyen phan tich anh huong cua kinh te vi mo My len tai san rui ro (bao gom crypto).\nDu lieu vi mo gan day:\n\n${lines.join('\n')}\n\nDua vao du lieu nay, danh gia trien vong CHUNG cho tai san rui ro/crypto trong boi canh vi mo hien tai.\nTra loi DUY NHAT mot JSON object, khong markdown, dung format:\n{"signal": "BUY|SELL|HOLD", "confidence": 0-100, "reason": "giai thich ngan gon dua tren cac chi so vi mo"}\n\nBUY = moi truong vi mo thuan loi cho tai san rui ro (lai suat giam, lam phat on dinh...), SELL = moi truong bat loi (lai suat tang, dola manh...), HOLD = trung tinh.`;

return [{ json: { prompt } }];

const raw = $input.first().json;

let contentText = '';
if (raw.choices && raw.choices[0] && raw.choices[0].message) {
  contentText = raw.choices[0].message.content || '';
}
const cleaned = contentText.replace(/```json|```/g, '').trim();

let parsed;
try { parsed = JSON.parse(cleaned); } catch (e) { parsed = null; }

if (!parsed || !parsed.signal) {
  parsed = { signal: 'HOLD', confidence: 0, reason: 'parse_error: AI khong tra ve JSON hop le' };
}

let conf = parseInt(parsed.confidence, 10);
if (isNaN(conf)) conf = null;

return [{ json: {
  signal: (parsed.signal || 'HOLD').toUpperCase(),
  confidence: conf,
  reason: parsed.reason || ''
} }];
